package com.wansheng.visitor.oa;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/internal/oa/processes") class OaCallbackController{private final OaProcessService service;private final String token;OaCallbackController(OaProcessService s,@Value("${visitor.oa.internal-token}")String t){service=s;token=t;}@PostMapping("/{visitId}/status")void status(@PathVariable String visitId,@RequestBody Status body,@RequestHeader(value="X-Internal-Token",required=false)String supplied){if(token.isBlank()||!token.equals(supplied))throw new ResponseStatusException(HttpStatus.FORBIDDEN);service.updateStatus(visitId,body.status());}record Status(String status){} }
